import java.util.Scanner;public class EvenNumbers {    public static void main(String[] args) {        Scanner sc = new Scanner(System.in);        System.out.print("Enter array length: ");        int n = sc.nextInt();        int[] arr = new int[n];        System.out.println("Enter elements:");        for (int i = 0; i < n; i++) {            arr[i] = sc.nextInt();        }        System.out.print("Even numbers: ");        for (int i = 0; i < n; i++) {            if (arr[i] % 2 == 0) {                System.out.print(arr[i] + " ");            }        }        sc.close();    }}class ReverseArray {    public static void main(String[] args) {        Scanner sc = new Scanner(System.in);        System.out.print("Enter array length: ");        int n = sc.nextInt();        int[] arr = new int[n];        System.out.println("Enter elements:");        for (int i = 0; i < n; i++) {            arr[i] = sc.nextInt();        }        for (int i = 0; i < n / 2; i++) {            int temp = arr[i];            arr[i] = arr[n - 1 - i];            arr[n - 1 - i] = temp;        }        System.out.print("Reversed array: ");        for (int i = 0; i < n; i++) {            System.out.print(arr[i] + " ");        }        sc.close();    }}